"""The main password (KAN-29): generated by the app and mandatory, the app side of `zbone backup setup`.

A page of the first start (`/benvenuto/password`), shown also after the update when the keys were made with a
passphrase chosen by hand. New keys: the app proposes a password (its rules can change), then shows it with the
recovery code once and asks two random groups of the code back; both can be saved in a «foglio di recupero».
Nothing is saved before that confirmation. Old keys: the old passphrase or the recovery code opens them, then the
same steps move them to the password (same key: every snapshot made before still opens). Afterwards the plain
snapshots are sealed and, with copies on Drive, the first copy is sent.
"""

from typing import Any, Callable, Dict, Optional

import flet as ft

from zibaldone.core import password as P
from zibaldone.core.brand import APP_NAME
from zibaldone.ui import cloud_model as cm
from zibaldone.ui import services
from zibaldone.ui import theme as T
from zibaldone.ui import widgets as W
from zibaldone.ui.context import AppContext
from zibaldone.ui.navigation import Route

INTRO_NEW = (
    "I tuoi backup li protegge una password creata da ZibaldOne: lunga e a caso, nessuno può indovinarla. "
    "Ogni backup è cifrato per intero: senza la password o il codice di recupero non si apre, da nessuno, nemmeno da chi ha creato l'app."
)
INTRO_OLD = (
    "Da questa versione i backup si proteggono con una password creata da ZibaldOne, più forte di una passphrase scelta a mano. "
    "Apri le chiavi con la tua vecchia passphrase, o con il codice di recupero, e passa alla password: i backup che hai già restano tutti apribili."
)
KIND_LABELS = (("lower", "Minuscole"), ("upper", "Maiuscole"), ("digits", "Numeri"), ("symbols", "Simboli"))


def setup_encryption(ctx: AppContext, on_done: Optional[Callable[[], Any]] = None) -> None:
    """The old «Attiva la cifratura» buttons lead to the password page."""
    ctx.go("/benvenuto/password")


class PasswordPicker:
    """The proposed password, «Rigenera» and the rules (kinds of characters, length, minimums)."""

    def __init__(self, ctx: AppContext) -> None:
        self.ctx = ctx
        self.rules = P.PasswordRules()
        self.value = P.generate(self.rules)
        self.shown = ft.Text(self.value, size=20, weight=ft.FontWeight.W_600, color=T.ACCENT, font_family="monospace", selectable=True, text_align=ft.TextAlign.CENTER)
        self.strength = W.caption("")
        self.error = W.error_text()
        self.kinds = {name: ft.Checkbox(label=label, value=True, on_change=self.changed) for name, label in KIND_LABELS}
        self.length_label = W.body("")
        self.length = ft.Slider(min=P.MIN_LENGTH, max=P.MAX_LENGTH, divisions=P.MAX_LENGTH - P.MIN_LENGTH, value=self.rules.length, active_color=T.ACCENT, on_change=self.changed)
        self.min_digits = W.text_input(str(self.rules.min_digits), label="Numeri, almeno", keyboard_type=ft.KeyboardType.NUMBER, width=150, on_change=self.changed)
        self.min_symbols = W.text_input(str(self.rules.min_symbols), label="Simboli, almeno", keyboard_type=ft.KeyboardType.NUMBER, width=150, on_change=self.changed)
        self.options = ft.Column(
            [ft.Row(list(self.kinds.values()), wrap=True, spacing=4), self.length_label, self.length, ft.Row([self.min_digits, self.min_symbols], wrap=True, spacing=12)],
            spacing=8,
            visible=False,
        )
        self.describe()

    def describe(self) -> None:
        self.length_label.value = f"Lunghezza: {self.rules.length} caratteri"
        self.strength.value = f"Forza: circa {int(self.rules.bits())} bit. Senza i caratteri che si confondono (l, I, O, 0, 1)."

    def read_rules(self) -> Optional[P.PasswordRules]:
        try:
            minimums = [int((field.value or "0").strip() or "0") for field in (self.min_digits, self.min_symbols)]
        except ValueError:
            self.error.value = "I minimi sono numeri: scrivi una cifra."
            return None
        kinds = {name: bool(box.value) for name, box in self.kinds.items()}
        rules = P.PasswordRules(length=int(self.length.value or P.MIN_LENGTH), min_digits=minimums[0], min_symbols=minimums[1], **kinds)
        problem = rules.problem()
        if problem:
            self.error.value = problem[0].upper() + problem[1:] + "."
            return None
        return rules

    def changed(self, _: Any = None) -> None:
        rules = self.read_rules()
        if rules is not None:
            self.rules = rules
            self.regenerate()
        self.error.visible = rules is None
        self.ctx.update(self.error)

    def regenerate(self, _: Any = None) -> None:
        self.value = P.generate(self.rules)
        self.shown.value = self.value
        self.describe()
        self.ctx.update(self.shown, self.strength, self.length_label)

    def toggle_options(self, _: Any = None) -> None:
        self.options.visible = not self.options.visible
        self.ctx.update(self.options)

    def build(self) -> ft.Control:
        return W.panel(
            ft.Column(
                [
                    W.caption("La tua password principale"),
                    ft.Container(self.shown, padding=12, bgcolor=T.BG, border_radius=T.RADIUS_SMALL, alignment=ft.Alignment.CENTER),
                    self.strength,
                    ft.Row([W.text_button("Rigenera", self.regenerate, icon="REFRESH"), W.text_button("Regole", self.toggle_options, icon="TUNE")], wrap=True, spacing=4),
                    self.options,
                    self.error,
                ],
                spacing=10,
                horizontal_alignment=ft.CrossAxisAlignment.STRETCH,
            )
        )


def password_step(ctx: AppContext, route: Route) -> ft.Control:
    """The mandatory page: the password for new keys, or the move from the old passphrase."""
    from zibaldone.ui.views.onboarding import brand

    keys = services.keys_api()
    folder = ctx.folder
    holder = ft.Column(spacing=14, horizontal_alignment=ft.CrossAxisAlignment.STRETCH)
    intro = W.body(INTRO_NEW, dim=True)

    def show_picker(private_key: Any = None) -> None:
        picker = PasswordPicker(ctx)
        error = W.error_text()
        go_on = W.primary_button("Usa questa password", None, icon="ARROW_FORWARD")

        def failed(problem: Exception) -> None:
            go_on.disabled = False
            error.value, error.visible = cm.error_text(problem), True
            ctx.update(go_on, error)

        def proceed(_: Any = None) -> None:
            chosen = picker.value
            if private_key is not None:
                code = keys.new_recovery_code()
                show_recovery(ctx, chosen, code, lambda: keys.renew(folder, private_key, chosen, code), private_key, ctx.advance)
                return
            go_on.disabled = True
            ctx.update(go_on)

            def created(new_keys: Any) -> None:
                go_on.disabled = False
                ctx.update(go_on)
                show_recovery(ctx, chosen, new_keys.recovery_code, lambda: keys.save_new_keys(folder, new_keys), new_keys.private_key, ctx.advance)

            ctx.run_blocking(lambda: keys.create_keys(chosen, generated=True), created, failed)

        go_on.on_click = proceed
        holder.controls = [
            picker.build(),
            W.caption("Non serve impararla: nel prossimo passo te la mostro con il codice di recupero e puoi salvarle in un foglio da stampare."),
            error,
            ft.Row([go_on], alignment=ft.MainAxisAlignment.END),
        ]
        ctx.update(holder)

    def show_unlock() -> None:
        secret = W.text_input("", label="Vecchia passphrase", password=True, can_reveal_password=True, autofocus=True)
        with_code = ft.Switch(label="Uso il codice di recupero", value=False, active_color=T.ACCENT)
        error = W.error_text()
        open_keys = W.primary_button("Apri le chiavi", None, icon="LOCK_OPEN")

        def switched(_: Any = None) -> None:
            secret.label = "Codice di recupero" if with_code.value else "Vecchia passphrase"
            secret.password = not with_code.value
            secret.capitalization = ft.TextCapitalization.CHARACTERS if with_code.value else ft.TextCapitalization.NONE
            ctx.update(secret)

        def failed(problem: Exception) -> None:
            open_keys.disabled = False
            wrong_passphrase = isinstance(problem, keys.WrongSecretError) and not with_code.value
            error.value = "Non è la vecchia passphrase: riprova, o usa il codice di recupero." if wrong_passphrase else cm.error_text(problem)
            error.visible = True
            ctx.update(open_keys, error)

        def unlock(_: Any = None) -> None:
            value = (secret.value or "").strip()
            if not value:
                error.value, error.visible = "Scrivi la vecchia passphrase o il codice di recupero.", True
                ctx.update(error)
                return
            open_keys.disabled = True
            ctx.update(open_keys)
            work = (lambda: keys.unlock_with_recovery_code(folder, value)) if with_code.value else (lambda: keys.unlock_with_passphrase(folder, value))
            ctx.run_blocking(work, show_picker, failed)

        def start_over() -> None:
            try:
                keys.retire(folder)
            except OSError as problem:
                failed(problem)
                return
            intro.value = INTRO_NEW
            ctx.update(intro)
            show_picker()

        def lost(_: Any = None) -> None:
            ctx.confirm(
                "Ricominciare con chiavi nuove?",
                "I backup cifrati che hai già non si apriranno più con la nuova password. Le vecchie chiavi restano da parte nella cartella dati, "
                "non le cancello: se ritrovi la passphrase si possono ancora usare. I dati di ZibaldOne su questo dispositivo restano tutti.",
                "Ricomincio con chiavi nuove",
                start_over,
                cancel_label="Torno indietro",
            )

        with_code.on_change = switched
        open_keys.on_click = unlock
        secret.on_submit = unlock
        holder.controls = [
            W.panel(ft.Column([W.wide(secret), with_code, error], spacing=10)),
            ft.Row([open_keys], alignment=ft.MainAxisAlignment.END),
            ft.Row([W.text_button("Non ricordo né la passphrase né il codice", lost, color=T.ERROR)], alignment=ft.MainAxisAlignment.END),
        ]

    try:
        moving = keys is not None and keys.is_configured(folder)
    except Exception:
        moving = False
    if keys is None:
        holder.controls = [W.coming_soon("La password dei backup è in arrivo.")]
    elif moving:
        intro.value = INTRO_OLD
        show_unlock()
    else:
        show_picker()
    return W.screen([brand(), W.title_with_nickname("La tua password", "Mnemosyne", size=22), intro, holder], ctx.wide)


def show_recovery(ctx: AppContext, password: str, code: str, store: Callable[[], Any], private_key: Any, on_done: Optional[Callable[[], Any]]) -> None:
    """The password and the recovery code, once; two groups of the code copied back before anything is saved."""
    asked = cm.recovery_groups_to_ask(code)
    answers: Dict[int, ft.TextField] = {
        number: W.text_input("", label=f"Gruppo {number}", autofocus=index == 0, width=130, capitalization=ft.TextCapitalization.CHARACTERS)
        for index, number in enumerate(asked)
    }
    error = W.error_text()
    attempts = {"left": cm.CONFIRM_ATTEMPTS}
    confirm = W.primary_button("Ho scritto tutto", None, icon="CHECK")

    sheet_note = W.caption("Foglio salvato. Stampalo o copialo su carta, poi cancella il file.", color=T.SUCCESS)
    sheet_note.visible = False

    def sheet_saved(_where: str) -> None:  # said inside the dialog: a toast would sit on top of it
        sheet_note.visible = True
        ctx.update(sheet_note)

    def save_sheet(_: Any = None) -> None:
        sheet = cm.recovery_sheet(password, code, ctx.now())
        ctx.save_file(cm.RECOVERY_SHEET_NAME, sheet.encode("utf-8"), sheet_saved)

    def check(_: Any = None) -> None:
        if not cm.recovery_groups_ok(code, {number: field.value or "" for number, field in answers.items()}):
            attempts["left"] -= 1
            if attempts["left"] <= 0:
                ctx.close_dialog()
                ctx.toast("Non ho salvato nulla: riprova quando vuoi, ti preparo un codice nuovo.", error=True)
                return
            error.value, error.visible = "Non corrisponde: ricontrolla i gruppi che hai scritto.", True
            ctx.update(error)
            return
        confirm.disabled = True
        ctx.update(confirm)
        finish(ctx, store, private_key, on_done)

    confirm.on_click = check
    for field in answers.values():
        field.on_submit = check

    def secret_box(label: str, value: str) -> ft.Control:
        return ft.Column(
            [W.caption(label), W.panel(ft.Text(value, size=17, weight=ft.FontWeight.W_600, color=T.ACCENT, font_family="monospace", selectable=True, text_align=ft.TextAlign.CENTER), padding=12, bgcolor=T.BG)],
            spacing=4,
            horizontal_alignment=ft.CrossAxisAlignment.STRETCH,
        )

    dialog = ft.AlertDialog(
        modal=True,
        scrollable=True,
        title="Password e codice di recupero",
        content=ft.Container(
            ft.Column(
                [
                    W.body("Te li mostro solo adesso. Scrivili su carta, o salva il foglio e stampalo, e tienili lontano da questo dispositivo.", size=14),
                    secret_box("Password principale", password),
                    secret_box("Codice di recupero", code),
                    ft.Row([W.secondary_button("Salva foglio di recupero", save_sheet, icon="DOWNLOAD")], alignment=ft.MainAxisAlignment.CENTER),
                    sheet_note,
                    W.caption(f"Il codice serve se perdi la password. Senza l'una e senza l'altro i backup di {APP_NAME} non si aprono, da nessuno."),
                    W.body("Per conferma, copia questi gruppi del codice:", size=14),
                    ft.Row(list(answers.values()), wrap=True, spacing=12),
                    error,
                ],
                spacing=12,
                tight=True,
                horizontal_alignment=ft.CrossAxisAlignment.STRETCH,
            ),
            width=480,
        ),
        actions=[W.text_button("Annulla", lambda _: (ctx.close_dialog(), ctx.toast("Non ho salvato nulla.")), color=T.TEXT), confirm],
        actions_alignment=ft.MainAxisAlignment.END,
    )
    ctx.show_dialog(dialog)


def finish(ctx: AppContext, store: Callable[[], Any], private_key: Any, on_done: Optional[Callable[[], Any]]) -> None:
    """Save the keys, seal the plain snapshots, then send the first copies when they go to Drive."""
    folder = ctx.folder

    def work() -> Any:
        store()
        backups = services.backups_api()
        if backups is not None and hasattr(backups, "encrypt_existing_snapshots"):
            return backups.encrypt_existing_snapshots(folder, private_key)
        return None

    def done(result: Any) -> None:
        ctx.close_dialog()
        message = "Password principale salvata: i backup sono cifrati per intero."
        sealed = list(getattr(result, "encrypted", []) or [])
        failed = list(getattr(result, "failed", []) or [])
        if sealed:
            message += f" Istantanee che c'erano già, ora cifrate: {len(sealed)}."
        if failed:
            message += f" {len(failed)} sono rimaste in chiaro perché rovinate."
        ctx.toast(message, error=bool(failed))
        from zibaldone.ui.views.cloud import after_encryption_setup

        after_encryption_setup(ctx, on_done)

    def failed(problem: Exception) -> None:
        ctx.close_dialog()
        ctx.toast(f"Password non salvata: {cm.error_text(problem)}", error=True)

    ctx.run_blocking(work, done, failed)
